const { roundCents } = require("./money");

function generateInvoices(ledgerEntries, opts = {}) {
  const { startDate = null, endDate = null, currency = "USD" } = opts;

  const invoices = new Map();

  for (const entry of ledgerEntries) {
    const entryDate = entry.date ? new Date(entry.date) : new Date();

    if (startDate && entryDate < startDate) continue;
    if (endDate && entryDate > endDate) continue;

    const key = `${entry.accountId}`;
    if (!invoices.has(key)) {
      invoices.set(key, {
        id: generateInvoiceId(entry.accountId, entryDate),
        customer: entry.accountId,
        date: entryDate.toLocaleDateString("en-US"),
        total: 0,
        currency: entry.currency || currency,
      });
    }

    const invoice = invoices.get(key);
    invoice.total += entry.kind === "credit" ? entry.amount : -entry.amount;
    invoice.total = roundCents(invoice.total);
  }

  return Array.from(invoices.values());
}

function generateInvoiceId(accountId, date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const hash = accountId.substring(0, 4).toUpperCase();
  return `INV-${year}${month}-${hash}`;
}

module.exports = { generateInvoices, generateInvoiceId };

