const http = require("http");
const url = require("url");
const { generateInvoices } = require("./invoices");
const { toCSV } = require("./csv");

const port = process.env.PORT || 4000;

const ledger = [];

http.createServer((req, res) => {
  const parsedUrl = url.parse(req.url, true);
  const pathname = parsedUrl.pathname;

  if (pathname === "/invoices/export.csv" && req.method === "GET") {
    const { start, end, currency } = parsedUrl.query;
    const startDate = start ? new Date(start) : null;
    const endDate = end ? new Date(end) : null;

    const invoices = generateInvoices(ledger, { startDate, endDate, currency });
    const csv = toCSV(invoices, ["id", "customer", "date", "total", "currency"]);

    res.writeHead(200, { "Content-Type": "text/csv; charset=utf-8" });
    res.end(csv);
  } else {
    res.end("billing ok\n");
  }
}).listen(port, () => console.log(`billing on :${port}`));

