const test = require("node:test");
const assert = require("node:assert");
const { toCSV, escapeCsvField } = require("../src/csv");

test("escapeCsvField: simple values", () => {
  assert.strictEqual(escapeCsvField("hello"), "hello");
  assert.strictEqual(escapeCsvField(123), "123");
});

test("escapeCsvField: values with commas", () => {
  assert.strictEqual(escapeCsvField("hello, world"), '"hello, world"');
});

test("escapeCsvField: values with quotes", () => {
  assert.strictEqual(escapeCsvField('say "hi"'), '"say ""hi"""');
});

test("escapeCsvField: values with newlines", () => {
  assert.strictEqual(escapeCsvField("line1\nline2"), '"line1\nline2"');
});

test("toCSV: basic", () => {
  const records = [
    { id: "1", name: "Alice", age: 30 },
    { id: "2", name: "Bob", age: 25 },
  ];
  const csv = toCSV(records, ["id", "name", "age"]);
  assert.strictEqual(csv, "id,name,age\n1,Alice,30\n2,Bob,25");
});

test("toCSV: with special characters", () => {
  const records = [
    { id: "1", name: "Alice, Inc.", note: 'says "hi"' },
  ];
  const csv = toCSV(records, ["id", "name", "note"]);
  assert.strictEqual(csv, 'id,"name","note"\n1,"Alice, Inc.","says ""hi"""');
});

