const test = require("node:test");
const assert = require("node:assert");
const { generateInvoices, generateInvoiceId } = require("../src/invoices");

test("generateInvoiceId", () => {
  const date = new Date("2026-09-15");
  const id = generateInvoiceId("cust-12345", date);
  assert.strictEqual(id, "INV-202609-CUST");
});

test("generateInvoices: empty ledger", () => {
  const invoices = generateInvoices([]);
  assert.strictEqual(invoices.length, 0);
});

test("generateInvoices: single account with credits and debits", () => {
  const ledger = [
    { accountId: "acc-1", amount: 100, kind: "credit", date: new Date("2026-09-01") },
    { accountId: "acc-1", amount: 30, kind: "debit", date: new Date("2026-09-01") },
  ];
  const invoices = generateInvoices(ledger);

  assert.strictEqual(invoices.length, 1);
  assert.strictEqual(invoices[0].customer, "acc-1");
  assert.strictEqual(invoices[0].total, 70);
  assert.strictEqual(invoices[0].currency, "USD");
});

test("generateInvoices: multiple accounts", () => {
  const ledger = [
    { accountId: "acc-1", amount: 100, kind: "credit", date: new Date("2026-09-01") },
    { accountId: "acc-2", amount: 50, kind: "credit", date: new Date("2026-09-01") },
  ];
  const invoices = generateInvoices(ledger);

  assert.strictEqual(invoices.length, 2);
});

test("generateInvoices: date filtering", () => {
  const ledger = [
    { accountId: "acc-1", amount: 100, kind: "credit", date: new Date("2026-08-15") },
    { accountId: "acc-1", amount: 50, kind: "credit", date: new Date("2026-09-15") },
    { accountId: "acc-1", amount: 25, kind: "credit", date: new Date("2026-10-15") },
  ];

  const startDate = new Date("2026-09-01");
  const endDate = new Date("2026-09-30");
  const invoices = generateInvoices(ledger, { startDate, endDate });

  assert.strictEqual(invoices.length, 1);
  assert.strictEqual(invoices[0].total, 50);
});

test("generateInvoices: respects currency from entry", () => {
  const ledger = [
    { accountId: "acc-1", amount: 100, kind: "credit", date: new Date("2026-09-01"), currency: "EUR" },
  ];
  const invoices = generateInvoices(ledger);

  assert.strictEqual(invoices[0].currency, "EUR");
});

