test("server: GET /invoices/export.csv returns CSV", async () => {
  // Note: This is a basic structural test. A full integration test would
  // start the actual server and make real HTTP requests.

  const { generateInvoices } = require("../src/invoices");
  const { toCSV } = require("../src/csv");

  const ledger = [
    { accountId: "cust-001", amount: 1000, kind: "credit", date: new Date("2026-09-15"), currency: "USD" },
    { accountId: "cust-001", amount: 200, kind: "debit", date: new Date("2026-09-15"), currency: "USD" },
  ];

  const invoices = generateInvoices(ledger);
  const csv = toCSV(invoices, ["id", "customer", "date", "total", "currency"]);

  // Verify CSV structure
  const lines = csv.split("\n");
  assert.strictEqual(lines[0], "id,customer,date,total,currency");
  assert.match(lines[1], /INV-202609-CUST/);
  assert.match(lines[1], /cust-001/);
  assert.match(lines[1], /800/);
});

